//! Map an incident to an ntfy message — the pure mapping at the heart of push delivery.

use bsc_incident::{Incident, Severity};

/// Map an incident to an ntfy message. PURE — no network, no clock.
///
/// The title names the severity and the kind; the body LEADS with the detector's own evidence line
/// (which itself leads with the frequency and received power an attacker cannot forge) and then adds
/// the coalescing context — which sensor, how many times, since when — so a burst reads as a burst.
pub fn ntfy_message(inc: &Incident, topic: &str) -> crate::NtfyMessage {
    let sev = match inc.severity {
        Severity::Info => "INFO",
        Severity::Low => "LOW",
        Severity::Medium => "MEDIUM",
        Severity::High => "HIGH",
        Severity::Critical => "CRITICAL",
    };
    let title = format!("{sev} — {}", crate::label_for(inc.kind));

    let mut body = inc.evidence.summary.clone();
    // The coalescing context turns "an alarm" into "an ongoing thing", which is the difference
    // between reacting once and understanding what is happening.
    if inc.count > 1 {
        body.push_str(&format!("\n\nSeen {}× on sensor '{}'.", inc.count, inc.source));
    } else {
        body.push_str(&format!("\n\nSensor '{}'.", inc.source));
    }

    crate::NtfyMessage {
        topic: topic.to_string(),
        title,
        priority: crate::priority_for(inc.severity),
        tags: crate::tags_for(inc.kind),
        body,
        markdown: false,
        click: None,
    }
}
